1/* Media query for small screens */
2@media (max-width: 380px) {
3    .form-row {
4        flex-direction: column;
5        /* Stack the input fields */
6    }
7
8    .form-group input,
9    .form-group select,
10    .form-group textarea {
11        width: 100%;
12        /* Ensure input fields take full width */
13    }
14
15    .contact-form-container {
16        padding: 20px;
17        /* Reduced padding for smaller screens */
18        margin: 0 20px;
19        /* Margin adjustment for smaller screens */
20    }
21
22    h1 {
23        font-size: 20px;
24        /* Smaller heading for mobile */
25    }
26
27    .submit-btn {
28        width: 100%;
29        /* Submit button takes full width */
30        margin-left: 0;
31        /* Remove auto left margin */
32    }
33}
